<script setup lang="ts">
import { ref, watch } from 'vue'
import { useSession } from '../domains/access/src'
import { ConfigurationEditor, configurationWorkspace } from '../domains/configuration/src'
import { RunsView } from '../domains/runs/src'
import type { Project } from '../domains/projects/src'
import type { Agent } from '../domains/infrastructure/src'
import { projectPath } from '../shared/api'
const workspace=configurationWorkspace();const session=useSession();const token=ref('');const message=ref('');const projects=ref<Project[]>([]);const project=ref('');const agents=ref<Agent[]>([]);const page=ref('Configuração');const theme=ref('light')
watch(theme,v=>document.documentElement.dataset.theme=v)
watch(()=>session.api,async (api,_,cleanup)=>{workspace.clear();projects.value=[];project.value='';agents.value=[];if(!api)return;let current=true;const c=new AbortController();cleanup(()=>{current=false;c.abort()});try{const p=await api<{projects:Project[]}>('/projects',undefined,c.signal);if(current)projects.value=p.projects}catch(e){if(current)message.value=String(e)}})
watch(project,async(p,_,cleanup)=>{agents.value=[];if(!p||!session.api)return;let current=true;const c=new AbortController();cleanup(()=>{current=false;c.abort()});try{const a=await session.api<{agents:Agent[]}>(projectPath(p)+'/agents',undefined,c.signal);if(current)agents.value=a.agents}catch(e){if(current)message.value=String(e)}})
async function enter(){const value=token.value;token.value='';try{await session.enter(value);message.value='Sessão verificada'}catch(e){message.value=String(e)}}
</script>
<template><a class="skip" href="#content">Ir ao conteúdo</a><header><strong class="brand">ec<span> / Controle de entregas</span></strong><label>Tema<select v-model="theme"><option value="light">Claro</option><option value="dark">Escuro</option></select></label><button v-if="session.api" @click="session.leave().catch(e=>message=String(e))">Revogar e sair</button></header>
<div class="shell"><aside><h1>Operação</h1><p>Projetos e pipelines</p><template v-if="session.api"><label>Projeto acessível<select v-model="project"><option value="">Selecione</option><option v-for="p in projects" :key="p.project" :value="p.project">{{p.project}} · {{p.role}}</option></select></label><nav aria-label="Contexto do projeto"><button v-for="p in ['Configuração','Execuções','Agentes']" :key="p" @click="page=p" :aria-current="page===p?'page':undefined">{{p}}</button></nav><p>{{session.identity}}<br>Expira: {{session.expires}}</p></template></aside>
<main id="content" tabindex="-1"><p role="status">{{message}}</p><form v-if="!session.api" @submit.prevent="enter"><h2>Entrar com sessão provisionada</h2><p>Use a sessão entregue pelo administrador local. Ela fica somente na memória desta aba.</p><label>Token de sessão<input v-model="token" type="password" autocomplete="off" required /></label><button>Verificar sessão</button></form>
<template v-else><p class="scope">Escopo / {{project || 'Nenhum projeto selecionado'}} / {{page}}</p><p v-if="!projects.length">Nenhum projeto acessível.</p><template v-if="project"><ConfigurationEditor v-if="page==='Configuração'" :key="session.generation+project" :api="session.api" :project="project" :can-write="projects.find(p=>p.project===project)?.role!=='viewer'"/><RunsView v-if="page==='Execuções'" :key="session.generation+project" :api="session.api" :project="project" :can-write="projects.find(p=>p.project===project)?.role!=='viewer'"/><section v-if="page==='Agentes'"><h2>Agentes do projeto</h2><p>Validade da sessão observada na consulta; não indica heartbeat ou capacidade garantida.</p><p v-if="!agents.length">Nenhum agente cadastrado.</p><article v-for="a in agents" :key="a.name"><h3>{{a.name}}</h3><p>{{a.revoked?'Revogado':a.sessionValid?'Sessão válida':'Sem sessão válida'}}</p></article></section></template></template></main></div></template>
